#!/usr/bin/env node
// Regenerate demo/stacks-data.js from the compose files on disk.
//
//   node scripts/sync-demo.mjs
//
// The demo imports the generated module, so it works from a static host with no
// fetch and no second copy of the YAML maintained by hand. test/stacks.test.js
// fails when the generated file is stale.

import { readdirSync, readFileSync, writeFileSync, statSync, existsSync } from "node:fs";
import { join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { buildCatalog } from "../src/catalog.js";

const root = resolve(fileURLToPath(new URL("..", import.meta.url)));
const stacksDir = join(root, "stacks");

const files = readdirSync(stacksDir)
  .filter((slug) => statSync(join(stacksDir, slug)).isDirectory())
  .sort()
  .map((slug) => ({
    slug,
    compose: readFileSync(join(stacksDir, slug, "docker-compose.yml"), "utf8"),
    envExample: readFileSync(join(stacksDir, slug, ".env.example"), "utf8"),
    readme: readFileSync(join(stacksDir, slug, "README.md"), "utf8"),
  }));

const data = buildCatalog(files);
const out = join(root, "demo/stacks-data.js");
const body = `// Generated by scripts/sync-demo.mjs from stacks/*/. Do not edit by hand.
// Run \`npm run sync-demo\` after changing a compose file or stack README.

export const STACKS = ${JSON.stringify(data, null, 2)};
`;
writeFileSync(out, body, "utf8");
console.log(`wrote ${out} with ${data.length} stacks`);
